import re

def solve(env, goal):
    match = re.search(r'examine the (\w+) with the (\w+)', goal)
    if not match:
        return
    obj1 = match.group(1)
    obj2 = match.group(2)

    def get_objects(obs):
        return [(m.group(1), m.group(2)) 
                for m in re.finditer(r' a (\w+) (\d+)', obs)]

    admissible = env.admissible()
    go_commands = [cmd for cmd in admissible if cmd.startswith("go to")]

    # First look at current location
    env.step("look")
    obj_list = get_objects(env.observation)
    for n, i in obj_list:
        if n == obj1:
            env.step(f"take {n} {i}")
            break
    for n, i in obj_list:
        if n == obj2:
            env.step(f"use {n} {i}")
            return

    # Search through go commands
    for cmd in go_commands:
        env.step(cmd)
        obj_list = get_objects(env.observation)
        found1 = False
        for n, i in obj_list:
            if n == obj1:
                env.step(f"take {n} {i}")
                found1 = True
                break
        if found1:
            # Check if obj2 is in the same location
            obj_list = get_objects(env.observation)
            for n, i in obj_list:
                if n == obj2:
                    env.step(f"use {n} {i}")
                    return

    # Search for obj2 in remaining locations
    for cmd in go_commands:
        env.step(cmd)
        obj_list = get_objects(env.observation)
        for n, i in obj_list:
            if n == obj2:
                env.step(f"use {n} {i}")
                return
